'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { loadSettings } = require('./settings.js');

test('valid JSON overrides defaults', () => {
  const s = loadSettings('{"retries": 5}');
  assert.strictEqual(s.retries, 5);
  assert.strictEqual(s.verbose, false);
});

test('empty object keeps defaults', () => {
  assert.deepStrictEqual(loadSettings('{}'), { retries: 3, verbose: false });
});

test('invalid JSON throws instead of silently using defaults', () => {
  assert.throws(() => loadSettings('{ not json'), (err) => {
    assert.match(err.message, /invalid settings JSON/);
    const detail = err.message.replace('invalid settings JSON', '').replace(/[^A-Za-z0-9]/g, '');
    assert.ok(detail.length >= 5, 'message must keep the original parse error detail');
    return true;
  });
});

