'use strict';

const DEFAULTS = { retries: 3, verbose: false };

function loadSettings(raw) {
  let data;
  try {
    data = JSON.parse(raw);
  } catch (err) {
    throw new Error('invalid settings JSON: ' + err.message);
  }
  return Object.assign({}, DEFAULTS, data);
}

module.exports = { loadSettings };
